ic="jiaobu",fightBackground="城镇室外",autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},hdroom0524={id="hdroom0524",name="平安南街",permission=1,mapHide="0",dsc="中央广场南面的大街，往北便是中央广场。果农们吆喝贩卖着干果，不时相互闲聊几句今年种下的果种。几个孩童也不知是从哪里寻了一个破窑罐，找了一把枯木枝，有模有样的投起壶来。",up="hdroom0518",down="hdroom0527",roomRoles={"hdnpc0522"},roomItems={},BgmDown="1",roomBgm="mache",roomBgmRule=2,stepMusic="jiaobu",fightBackground="城镇室外",autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},hdroom0525={id="hdroom0525",name="庙会戏台",permission=1,mapHide="0",dsc="打北面新来的戏班，说着北方话，同平安小镇的人交谈起来倒也爽快利落。表演时因戏目独特，引得不少镇民和江湖人士闻声而来，坐下皆满，远远便能听到叫好声。即便是一知半解的顽童，也能定下心来听上一曲。",up="hdroom0519",roomRoles={"hdnpc0523","hdnpc0524"},roomItems={},BgmDown="1",roomBgm="mache",roomBgmRule=2,stepMusic="jiaobu",fightBackground="城镇室外",autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},hdroom0526={id="hdroom0526",name="比武台",permission=1,mapHide="0",dsc="这里是比武的擂台。擂台上缚着红色的绸带，两侧立有木牌，写着擂主与打擂之人的名号。一桌赌席开在左侧，又有庄家吆喝着买定离手。几个江湖草莽蓄势待发，正松快着筋骨准备走上擂台。",up="hdroom0520",roomRoles={},roomItems={},BgmDown="1",roomBgm="mache",roomBgmRule=2,stepMusic="jiaobu",fightBackground="城镇室外",autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},hdroom0527={id="hdroom0527",name="平安南街",permission=1,mapHide="0",dsc="中央广场南面的大街，往北便是中央广场。果农们吆喝贩卖着干果，不时相互闲聊几句今年种下的果种。几个孩童也不知是从哪里寻了一个破窑罐，找了一把枯木枝，有模有样的投起壶来。",up="hdroom0524",down="hdroom0528",right="hdroom0546",roomRoles={"hdnpc0525","hdnpc0526"},roomItems={},BgmDown="1",roomBgm="mache",roomBgmRule=2,stepMusic="jiaobu",fightBackground="城镇室外",autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},hdroom0528={id="hdroom0528",name="平安南街",permission=1,mapHide="0",dsc="中央广场南面的大街，往北便是中央广场。果农们吆喝贩卖着干果，不时相互闲聊几句今年种下的果种。几个孩童也不知是从哪里寻了一个破窑罐，找了一把枯木枝，有模有样的投起壶来。",up="hdroom0527",down="hdroom0529",roomRoles={},roomItems={},BgmDown="1",roomBgm="mache",roomBgmRule=2,stepMusic="jiaobu",fightBackground="城镇室外",autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},hdroom0529={id="hdroom0529",name="流樱湖",permission=1,mapHide="0",dsc="一片清澈的湖水，四面环柳，湖中画舫往来，四周挂着彩灯，将湖水映照得犹如白昼。湖畔每棵树上都挂着小小的彩灯，此时都在随风摇荡着，一片火光粼粼，煞是好看。湖中的画舫隐隐传开谈笑声。",up="hdroom0528",left="hdroom0551",roomRoles={},roomItems={},BgmDown="1",roomBgm="mache",roomBgmRule=2,stepMusic="jiaobu",fightBackground="城镇室外",autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},hdroom0530={id="hdroom0530",name="菜来饭馆",permission=1,mapHide="0",dsc="二层高的酒楼。门口停着一辆马车，上头运满了新到的时蔬，听闻从西南请了一个新厨子，多了不少的新菜式。又因此时各派江湖人士齐聚，所以菜色多样，席间热闹非凡。",left="hdroom0510",right="hdroom0531",roomRoles={"hdbs0514"},roomItems={},BgmDown="1",roomBgm="mache",roomBgmRule=2,stepMusic="jiaobu",fightBackground="城镇室外",autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},hdroom0531={id="hdroom0531",name="后厨",permission=1,mapHide="0",dsc="酒馆的后厨房，大厨们正忙着烧菜，一旁的碗筷堆积着，无人清洗。",left="hdroom0530",roomRoles={},roomItems={},BgmDown="1",roomBgm="mache",roomBgmRule=2,stepMusic="jiaobu",fightBackground="城镇室外",autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},hdroom0532={id="hdroom0532",name="后寺",permission=1,mapHide="0",dsc="这里是浮云寺的后寺，寺院正中有一个几人抱的大树。",left="hdroom0522",roomRoles={},roomItems={},BgmDown="1",roomBgm="mache",roomBgmRule=2,stepMusic="jiaobu",fightBackground="城镇室外",autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},hdroom0533={id="hdroom0533",name="村外土路",permission=1,mapHide="0",dsc="一条村子郊外的土路。由于是泥土建成，下雨的季节就会变得泥泞不堪。土路两旁郁郁葱葱，远处都是大片的农田。路边有人正在田间寻找野菜。",down="hdroom0536",right="hdroom0534",roomRoles={"hdnpc0527"},roomItems={},BgmDown="1",roomBgm="mache",roomBgmRule=2,stepMusic="jiaobu",fightBackground="城镇室外",autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},hdroom0534={id="hdroom0534",name="村外土路",permission=1,mapHide="0",dsc="一条村子郊外的土路。由于是泥土建成，下雨的季节就会变得泥泞不堪。土路两旁郁郁葱葱，远处都是大片的农田。再往前走便是村郊了。",up="hdroom0550",left="hdroom0533",right="hdroom0535",roomRoles={},roomItems={"hdbs0515"},BgmDown="1",roomBgm="mache",roomBgmRule=2,stepMusic="jiaobu",fightBackground="城镇室外",autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},hdroom0535={id="hdroom0535",name="平丘山",permission=1,mapHide="0",dsc="平安小镇之外的一处不高的小山。此处山势平缓，山路沿途均栽种有桃、柳之树，此时春暖花开，飞燕成群，是一处使人诗兴大发的好去处。几名才子佳人正在此处吟诗作对。",left="hdroom0534",rightUp="hdroom0554",roomRoles={},roomItems={"hdbs0516"},BgmDown="1",roomBgm="mache",roomBgmRule=2,stepMusic="jiaobu",fightBackground="城镇室外",autoCondition1={relation="and",conditions={}},au