and",conditions={}},autoResult6={}},hdroom0553={id="hdroom0553",name="篱笆小院",permission=1,mapHide="0",dsc="一间新建的篱笆小院，院前种了一棵桂花树，树下倚着锄头、箩筐，周围生满野花。院内一间普通茅屋，屋前挂有高粱、玉米，看起来十分古朴。院主人似乎刚刚搬来此地不久。",right="hdroom0502",roomRoles={"hdnpc0545a"},roomItems={"hdbs0529"},BgmDown="1",roomBgm="mache",roomBgmRule=2,stepMusic="jiaobu",fightBackground="城镇室外",autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},hdroom0554={id="hdroom0554",name="温泉",permission=1,mapHide="0",dsc="平安小镇外的一处温泉，水汽氤氲，温暖无比。泉内设了数个小隔间，隔间门上挂着火红的灯笼。",right="hdroom0556",leftDown="hdroom0535",roomRoles={},roomItems={},BgmDown="1",roomBgm="mache",roomBgmRule=2,stepMusic="jiaobu",fightBackground="城镇室外",autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},hdroom0555={id="hdroom0555",name="北巷口",permission=1,mapHide="0",dsc="北内大街一旁的小巷，里面深邃幽暗堆放着不少杂物，很少有人进去。",down="hdroom0505",roomRoles={},roomItems={},BgmDown="1",roomBgm="mache",roomBgmRule=2,stepMusic="jiaobu",fightBackground="城镇室外",autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},hdroom0556={id="hdroom0556",name="树林",permission=1,mapHide="1",dsc="